57:     const message = inputField.value.trim();
58:     if (!message) return;
59: 
60:     // Append User Message
61:     appendMessage('Anda', message, 'user');
62:     inputField.value = '';
63: 
64:     // Simulate AI loading
65:     const typingId = 'typing-' + Date.now();
66:     appendMessage('AI', 'Sedang memikirkan jawaban...', 'coach', typingId);
67: 
68:     const apiKey = localStorage.getItem('gemini_api_key');
69:     
70:     if (apiKey) {
71:         try {
72:             const response = await callGeminiAPI(apiKey, message);
73:             updateMessage(typingId, response);
74:         } catch (error) {
75:             updateMessage(typingId, 'Maaf, terjadi kesalahan saat menghubungi API Gemini: ' + error.message);
76:         }
77:     } else {
78:         // Fallback / Offline (Local RAG) Simulation
79:         setTimeout(() => {
80:             const simulatedResponse = simulateAIResponse(message);
81:             updateMessage(typingId, simulatedResponse);
82:         }, 1500);
83:     }
84: }
