131: async function callGeminiAPI(apiKey, message) {
132:     // We are using gemini-1.5-pro or gemini-1.5-flash which are the modern ones.
133:     const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${apiKey}`;
134:     
135:     // Definisi Knowledge Base / Dokumen Rujukan (RAG Lokal)
136:     // Anda bisa mengisi string ini dengan SOP, manual polis asuransi, atau aturan spesifik perusahaan.
137:     const KNOWLEDGE_BASE = `
138:         PANDUAN ASURANSI ASM ACADEMY:
139:         - ASM Auto Protection memberikan perlindungan komprehensif dengan rate dasar OJK 2.290% untuk Kategori 3 Wilayah II.
140:         - Asuransi Properti memiliki rate khusus berdasarkan kelas konstruksi. Kelas 1 (Tembok Beton) memiliki rate terendah.
141:         - Prosedur Klaim: Pelaporan maksimal 3x24 jam sejak kejadian. Dokumen wajib: Formulir klaim, foto kerugian, fotokopi polis/KTP.
142:         - Pengecualian Umum: Kerugian yang disengaja oleh tertanggung tidak dijamin dalam polis manapun.
143:     `;
144: 
145:     const prompt = `Anda adalah AI Insurance Coach bernama Coach. Anda adalah pakar asuransi umum Indonesia, ahli produk, dan mentor agen asuransi.
146: 
147: ATURAN SANGAT PENTING (Mencegah Halusinasi):
148: 1. Jika ada DOKUMEN PENGETAHUAN berupa file PDF yang dilampirkan, atau Teks di bawah ini, Anda HANYA BOLEH menjawab berdasarkan informasi tersebut.
149: 2. JANGAN MENGARANG (halusinasi) atau memberikan informasi di luar dokumen lampiran/teks tersebut.
150: 3. Jika jawaban dari pertanyaan agen tidak ditemukan di dalam DOKUMEN PENGETAHUAN, Anda WAJIB menjawab dengan tegas: "Maaf, informasi tersebut tidak terdapat dalam panduan produk (Knowledge Base) yang saya miliki."
151: 
152: --- TEKS DOKUMEN TAMBAHAN ---
153: ${KNOWLEDGE_BASE}
154: ---------------------------
155: 
156: Pertanyaan dari agen:
157: ${message}
158: `;
159: 
160:     const parts = [{ text: prompt }];
161: 
162:     const pdfBase64 = await loadPdfFromDB();
163:     if (pdfBase64) {
164:         parts.push({
165:             inlineData: {
166:                 mimeType: "application/pdf",
167:                 data: pdfBase64
168:             }
169:         });
170:     }
171: 
172:     const payload = {
173:         contents: [{
174:             parts: parts
175:         }]
176:     };
177: 
178:     const response = await fetch(url, {
179:         method: 'POST',
180:         headers: {
181:             'Content-Type': 'application/json'
182:         },
183:         body: JSON.stringify(payload)
184:     });
185: 
186:     if (!response.ok) {
187:         const errorData = await response.json();
188:         throw new Error(errorData.error?.message || 'Gagal menghubungi API');
189:     }
190: 
191:     const data = await response.json();
192:     if (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) {
193:         return data.candidates[0].content.parts[0].text;
194:     } else {
195:         throw new Error('Format respons tidak dikenali dari API');
196:     }
197: }
