199: function simulateAIResponse(message) {
200:     const lowerMessage = message.toLowerCase();
201:     if (lowerMessage.includes('polis') || lowerMessage.includes('klausul')) {
202:         return "Berdasarkan polis standar asuransi umum, terdapat klausul utama yang harus dipahami seperti jaminan dasar dan perluasan. Apakah Anda ingin menanyakan klausul produk spesifik seperti Asuransi Kendaraan Bermotor atau Kebakaran?";
203:     } else if (lowerMessage.includes('premi') || lowerMessage.includes('hitung')) {
204:         return "Untuk menghitung premi, Anda bisa menggunakan Simulator Premi di menu utama. Anda perlu mengetahui Kategori Kendaraan, Nilai Pertanggungan, dan Wilayah. Rumusnya adalah: **Nilai Pertanggungan x Rate OJK (%)**.";
205:     } else if (lowerMessage.includes('klaim')) {
206:         return "Proses klaim asuransi umumnya membutuhkan pelaporan maksimal 3x24 jam sejak kejadian. Dokumen wajib meliputi: formulir klaim, foto kerugian, dan fotokopi polis/KTP.";
207:     } else {
208:         return "Pertanyaan yang bagus. Sebagai mentor Anda, saya menyarankan untuk selalu memahami kebutuhan nasabah (Fact Finding) sebelum menawarkan produk. Ada hal spesifik tentang produk asuransi yang ingin didiskusikan?";
209:     }
210: }
