212: // ==================== INDEXED DB LOGIC FOR PDF ====================
213: const DB_NAME = 'AICoachDB';
214: const STORE_NAME = 'pdfStore';
215: 
216: function initDB() {
217:     return new Promise((resolve, reject) => {
218:         const request = indexedDB.open(DB_NAME, 1);
219:         request.onupgradeneeded = (e) => {
220:             const db = e.target.result;
221:             if (!db.objectStoreNames.contains(STORE_NAME)) {
222:                 db.createObjectStore(STORE_NAME);
223:             }
224:         };
225:         request.onsuccess = () => resolve(request.result);
226:         request.onerror = () => reject(request.error);
227:     });
228: }
229: 
230: async function savePdfToDB(base64Data) {
231:     const db = await initDB();
232:     return new Promise((resolve, reject) => {
233:         const tx = db.transaction(STORE_NAME, 'readwrite');
234:         const store = tx.objectStore(STORE_NAME);
235:         store.put(base64Data, 'knowledge_pdf');
236:         tx.oncomplete = () => resolve();
237:         tx.onerror = () => reject(tx.error);
238:     });
239: }
240: 
241: async function loadPdfFromDB() {
242:     const db = await initDB();
243:     return new Promise((resolve, reject) => {
244:         const tx = db.transaction(STORE_NAME, 'readonly');
245:         const store = tx.objectStore(STORE_NAME);
246:         const request = store.get('knowledge_pdf');
247:         request.onsuccess = () => resolve(request.result);
248:         request.onerror = () => reject(request.error);
249:     });
250: }
251: 
252: async function handlePdfUpload(event) {
253:     const file = event.target.files[0];
254:     if (!file) return;
255:     
256:     const statusText = document.getElementById('pdf-status-text');
257:     if (statusText) {
258:         statusText.style.color = 'var(--primary-blue)';
259:         statusText.innerText = "⏳ Sedang memproses PDF...";
260:     }
261: 
262:     const reader = new FileReader();
263:     reader.onload = async function(e) {
264:         const dataUrl = e.target.result;
265:         // Extract base64 part
266:         const base64Data = dataUrl.split(',')[1];
267:         try {
268:             await savePdfToDB(base64Data);
269:             if (statusText) {
270:                 statusText.style.color = 'var(--success-green)';
271:                 statusText.innerText = "✅ PDF Knowledge Base berhasil diunggah dan disimpan!";
272:             }
273:         } catch(err) {
274:             if (statusText) {
275:                 statusText.style.color = 'var(--danger-red)';
276:                 statusText.innerText = "❌ Gagal menyimpan PDF: " + err.message;
277:             }
278:         }
279:     };
280:     reader.readAsDataURL(file);
281: }
