const trainerModules = paCoachings.map(c => {
    let checklistHTML = "";
    if (c.checklist) {
        const listItems = c.checklist.split('\n').filter(l => l.trim() !== "");
        if (listItems.length > 0) {
            checklistHTML = "<h4 style='margin-top:20px'>✅ Checklist Target Praktek:</h4><ul>" + listItems.map(item => `<li>${item}</li>`).join('') + "</ul>";
        }
    }

