    if (c.goal) extraInfo += `<p><strong>Tujuan:</strong> ${c.goal}</p>`;
    if (c.summary) extraInfo += `<p><strong>Ringkasan:</strong> ${c.summary}</p>`;
    if (c.duration) extraInfo += `<p><strong>Target Waktu:</strong> ${c.duration} Hari</p>`;
    if (c.video) extraInfo += `<p><strong>Video:</strong> <a href="${c.video}" target="_blank" style="color:#007bff; text-decoration:underline;">Tonton Pembelajaran</a></p>`;
