window.findAIProduct = async function() {
    const typeEl = document.querySelector('input[name="ai-find-type"]:checked');
    const objEl = document.getElementById('ai-find-obj');
    const needsEl = document.getElementById('ai-find-needs');

    if (!needsEl.value.trim()) {
        alert("Silakan isi kebutuhan spesifik nasabah terlebih dahulu.");
        return;
    }

    const type = typeEl ? typeEl.value : '';
    const obj = objEl ? objEl.value : '';
    const needs = needsEl.value.trim();

    const btn = document.getElementById('btn-ai-find');
    const resultDiv = document.getElementById('ai-find-result');

    // UI Loading state
    const originalBtnText = btn.innerHTML;
    btn.innerHTML = "⏳ AI sedang menganalisis profil nasabah...";
    btn.disabled = true;
    resultDiv.style.display = 'none';

    const prompt = `Sebagai konsultan Asuransi Sinar Mas, berikan rekomendasi maksimal 2 produk asuransi Sinar Mas yang paling tepat untuk profil berikut: Jenis Nasabah: ${type}, Objek Asuransi: ${obj}, Kebutuhan Spesifik: ${needs}. Jawab HANYA dengan format HTML ringan. Gunakan bullet points untuk '🎯 Produk yang Direkomendasikan' dan paragraf singkat untuk '💡 Alasan'.`;

    try {
        const apiKey = localStorage.getItem('gemini_api_key');
        let responseHTML = "";

        if (apiKey && typeof callGeminiAPI === 'function') {
            responseHTML = await callGeminiAPI(apiKey, prompt);
            // Replace markdown block syntax if LLM includes it
            responseHTML = responseHTML.replace(/```html/g, '').replace(/```/g, '');
        } else {
            // Fallback Mock Response (Local Simulation)
            await new Promise(r => setTimeout(r, 2000));
            responseHTML = `
                <h4 style="margin-top:0; color:#0f172a;">🎯 Produk yang Direkomendasikan:</h4>
                <ul style="margin-bottom:15px; padding-left:20px;">
                    <li><strong>Simas ${obj} Optima</strong> - Perlindungan komprehensif untuk nasabah ${type.toLowerCase()}.</li>
                    <li><strong>Simas Perlindungan Ekstra</strong> - Perlindungan tambahan yang mencakup kebutuhan khusus: <em>${needs}</em>.</li>
                </ul>
                <h4 style="margin-top:0; color:#0f172a;">💡 Alasan:</h4>
                <p style="margin:0;">Berdasarkan profil nasabah dengan objek ${obj}, produk ini memberikan jaminan paling luas untuk menutup risiko dari spesifikasi yang disebutkan dengan perhitungan premi yang sangat kompetitif.</p>
            `;
        }

        resultDiv.innerHTML = responseHTML;
        resultDiv.style.display = 'block';
    } catch (e) {
        resultDiv.innerHTML = `<p style="color:#ef4444; margin:0;">Maaf, terjadi kesalahan saat menghubungi AI: ${e.message}</p>`;
        resultDiv.style.display = 'block';
    } finally {
        btn.innerHTML = originalBtnText;
        btn.disabled = false;
    }
};

